for (const [code, values] of Object.entries(UI_CORE)) T[code as Lang] = {...T[code as Lang], ...values};
function mapsUrl(a:string,b:string){return "https://www.google.com/maps/dir/?api=1&origin="+encodeURIComponent(a)+"&destination="+encodeURIComponent(b)+"&travelmode=driving"}
function save<T>(key:string,value:T){try{localStorage.setItem(key,JSON.stringify(value))}catch{}}
function load<T>(key:string,fallback:T):T{try{const v=localStorage.getItem(key);return v?JSON.parse(v):fallback}catch{return fallback}}
type QueuedAction={id:string,url:string,method:"POST",body:unknown};
function queueAction(action:QueuedAction){const current=load<QueuedAction[]>("ethio_transport_sync_queue",[]);save("ethio_transport_sync_queue",[...current,action].slice(-50))}
async function flushQueuedActions(){if(!navigator.onLine)return;const current=load<QueuedAction[]>("ethio_transport_sync_queue",[]);if(!current.length)return;const remaining:QueuedAction[]=[];for(const item of current){try{const r=await fetch(item.url,{method:item.method,headers:{"content-type":"application/json"},body:JSON.stringify(item.body)});if(!r.ok)remaining.push(item)}catch{remaining.push(item)}}save("ethio_transport_sync_queue",remaining)}

export default function Home(){
 const [lang,setLang]=useState<Lang>("am"), [active,setActive]=useState<ServiceId|null>(null), [heroIndex,setHeroIndex]=useState(0), [cardVisualIndex,setCardVisualIndex]=useState(0);
 const [origin,setOrigin]=useState(""),[destination,setDestination]=useState(""),[tripDate,setTripDate]=useState("");
 const [fareKm,setFareKm]=useState(""),[fareRate,setFareRate]=useState(""),[fareResult,setFareResult]=useState<number|null>(null),[fareType,setFareType]=useState("bus"),[fareSource,setFareSource]=useState(""),[fareLoading,setFareLoading]=useState(false);
 const [routeData,setRouteData]=useState<any>(null),[routeLoading,setRouteLoading]=useState(false);
 const [coords,setCoords]=useState<{lat:number,lon:number}|null>(null),[status,setStatus]=useState(""),[ref,setRef]=useState("");
 const [report,setReport]=useState({name:"",phone:"",category:"Fare / overcharge",description:"",location:""});
 const [trip,setTrip]=useState({origin:"",destination:"",time:"",notes:""}),[savedTrips,setSavedTrips]=useState<any[]>([]);
 const [accessNeed,setAccessNeed]=useState("Wheelchair access"),[parcel,setParcel]=useState({from:"",to:"",description:""});
 const [ticketProviders,setTicketProviders]=useState<any[]>([]),[operatorProviders,setOperatorProviders]=useState<any[]>([]),[emergencyContacts,setEmergencyContacts]=useState<any[]>([]);
 const L=T[lang], selected=serviceData.find(x=>x.id===active);
 const ticketItems=ticketProviders.length?ticketProviders.map(p=>{const base=ticketPlatforms.find(x=>x.name===p.name)||ticketPlatforms[0];return {name:p.name,meta:p.source_id?.organization_name||"Verified provider",url:p.booking_url,image:base.image}}):ticketPlatforms;
 const operatorItems=operatorProviders.length?operatorProviders.map((p,i)=>{const base=operators.find(x=>x[0]===p.name)||operators[i%operators.length];return {name:p.name,image:base?.[1]||operators[0][1],url:p.booking_url,source:p.source_id?.organization_name||"Verified source"}}):operators.map(([name,image])=>({name,image,url:"https://i-ticket.et/",source:"Ticket directory"}));

 useEffect(()=>{setLang(load<Lang>("ethio_transport_lang","am"));setSavedTrips(load("ethio_transport_trips",[]));flushQueuedActions();const onOnline=()=>flushQueuedActions();window.addEventListener("online",onOnline);return()=>window.removeEventListener("online",onOnline)},[]);
 useEffect(()=>{const id=window.setInterval(()=>setHeroIndex(i=>(i+1)%heroSlides.length),6500);return()=>window.clearInterval(id)},[]);
 useEffect(()=>{const id=window.setInterval(()=>setCardVisualIndex(i=>(i+1)%3),5200);return()=>window.clearInterval(id)},[]);
 useEffect(()=>save("ethio_transport_lang",lang),[lang]);
 useEffect(()=>{document.documentElement.lang=lang==="am"?"am":lang==="ao"?"om":lang},[lang]);
 useEffect(()=>{if(active==="ticket"){fetch("/api/tickets",{cache:"no-store"}).then(r=>r.ok?r.json():null).then(d=>{if(Array.isArray(d?.providers))setTicketProviders(d.providers)}).catch(()=>{});fetch("/api/operators",{cache:"no-store"}).then(r=>r.ok?r.json():null).then(d=>{if(Array.isArray(d?.operators))setOperatorProviders(d.operators)}).catch(()=>{});} if(active==="emergency"){fetch("/api/emergency",{cache:"no-store"}).then(r=>r.ok?r.json():null).then(d=>{if(Array.isArray(d?.contacts))setEmergencyContacts(d.contacts)}).catch(()=>{});}},[active]);
 const reportReady=useMemo(()=>report.description.trim().length>=5,[report.description]);

 function locate(){if(!navigator.geolocation){setStatus("GPS is not supported.");return} navigator.geolocation.getCurrentPosition(p=>{const c={lat:p.coords.latitude,lon:p.coords.longitude};setCoords(c);setReport(x=>({...x,location:x.location||c.lat.toFixed(6)+", "+c.lon.toFixed(6)}));setStatus("Location captured.")},()=>setStatus("Could not read location."))}
 async function findRoute(e:FormEvent){
   e.preventDefault();
   if(!origin.trim()||!destination.trim()){setStatus(lang==="am"?"መነሻና መድረሻ ያስገቡ።":lang==="en"?"Enter origin and destination.":"Ka'umsaa fi ga'umsaa galchi.");return}
   setRouteLoading(true);setRouteData(null);setStatus("");
   try{
    const r=await fetch("/api/routes?origin="+encodeURIComponent(origin)+"&destination="+encodeURIComponent(destination),{cache:"no-store"});
    const d=await r.json();
    if(!r.ok)throw new Error(d.error||"Route unavailable");
    setRouteData(d);
   }catch(e:any){setStatus(e?.message||"Route service unavailable.");}
   finally{setRouteLoading(false);}
  }
  async function loadVerifiedFare(){
   setFareLoading(true);setFareResult(null);setFareSource("");
   try{
    const r=await fetch("/api/fares?serviceType="+encodeURIComponent(fareType),{cache:"no-store"});
    const d=await r.json();
    if(!r.ok)throw new Error(d.error||"Fare service unavailable.");
    const row=d.fares?.[0];
    if(!row){setFareRate("");setStatus(lang==="am"?"ለዚህ አገልግሎት የተረጋገጠ ንቁ ታሪፍ አልተገኘም።":lang==="en"?"No verified active fare is currently available for this service.":"Tajaajila kanaaf kaffaltiin mirkanaa'e amma hin jiru.");return}
    setFareRate(String(row.rate_per_km ?? ""));
    setFareSource(row.source_id?.organization_name ? "Verified source: "+row.source_id.organization_name : "Verified fare record");
    if(row.minimum_fare!=null)setStatus("Minimum fare: "+row.minimum_fare+" "+(row.currency||"ETB"));
    else setStatus("");
   }catch(e:any){setStatus(e?.message||"Fare service unavailable.");}
   finally{setFareLoading(false);}
  }
 async function addTrip(){if(!trip.origin.trim()||!trip.destination.trim()){setStatus("Enter origin and destination.");return}const createdAt=new Date().toISOString();const id=crypto.randomUUID();const next=[{...trip,id,createdAt},...savedTrips].slice(0,20);setSavedTrips(next);save("ethio_transport_trips",next);setStatus(L.saved);try{if(trip.time){const body={reference:"ET-TRIP-"+id,origin:trip.origin,destination:trip.destination,plannedAt:new Date(trip.time).toISOString(),notes:trip.notes};const r=await fetch("/api/trip-proofs",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)});if(!r.ok)queueAction({id:"trip-"+id,url:"/api/trip-proofs",method:"POST",body})}}catch{if(trip.time)queueAction({id:"trip-"+id,url:"/api/trip-proofs",method:"POST",body:{reference:"ET-TRIP-"+id,origin:trip.origin,destination:trip.destination,plannedAt:new Date(trip.time).toISOString(),notes:trip.notes}})}}
 async function submitReport(e:FormEvent){e.preventDefault();const id="ET-"+new Date().toISOString().replace(/\D/g,"").slice(0,14)+"-"+Math.random().toString(36).slice(2,7).toUpperCase();const payload={...report,reference:id,createdAt:new Date().toISOString(),coordinates:coords};try{const r=await fetch("/api/complaints",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});if(r.ok){const d=await r.json();setRef(d.reference||id);setStatus(L.received);return}queueAction({id:"complaint-"+id,url:"/api/complaints",method:"POST",body:payload})}catch{queueAction({id:"complaint-"+id,url:"/api/complaints",method:"POST",body:payload})}save("ethio_transport_reports",[payload,...load<any[]>("ethio_transport_reports",[])].slice(0,50));setRef(id);setStatus(L.pending)}
 function saveAccess(){save("ethio_transport_accessibility",{need:accessNeed,savedAt:new Date().toISOString()});setStatus(L.saved)}
 function saveParcel(){if(!parcel.from||!parcel.to||!parcel.description){setStatus("Complete the form first.");return}save("ethio_transport_parcel",parcel);setStatus(L.saved)}

 return <main className="app">
  <header className="top"><div><div className="brand">ETHIO TRANSPORT</div><div className="sub">{L.sub}</div></div><select aria-label="Language" value={lang} onChange={e=>setLang(e.target.value as Lang)}>{LANG_OPTIONS.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select></header>

  <section className="hero" aria-label="ETHIO TRANSPORT">
   <div className="hero-slides" aria-hidden="true">{heroSlides.map((slide,i)=><div key={slide.image} className={"hero-slide "+(i===heroIndex?"active":"")} style={{backgroundImage:"url("+slide.image+")"}} />)}</div>
   <div className="hero-overlay"></div>
   <div className="hero-copy"><span className="eyebrow">SMART MOBILITY • ETHIOPIA</span><div className="heritage-line">ኢትዮጵያ ምድረ ቀደምት</div><h1>{lang==="am"?heroSlides[heroIndex].am:lang==="en"?heroSlides[heroIndex].en:heroSlides[heroIndex].ao}</h1><p>{lang==="am"?heroSlides[heroIndex].subAm:lang==="en"?heroSlides[heroIndex].subEn:heroSlides[heroIndex].subAo}</p><div className="hero-wish">{lang==="am"?heroSlides[heroIndex].wishAm:lang==="en"?heroSlides[heroIndex].wishEn:heroSlides[heroIndex].wishAo}</div><div className="transport-chips"><span>🚕 {lang==="am"?"ታክሲ":lang==="en"?"Taxi":"Taaksii"}</span><span>🚌 {lang==="am"?"አውቶቡስ":lang==="en"?"Bus":"Baasii"}</span><span>🚆 {lang==="am"?"ባቡር":lang==="en"?"Rail":"Baabura"}</span><span>✈️ {lang==="am"?"አየር":lang==="en"?"Air":"Xiyyaara"}</span></div></div>
   <div className="hero-controls" aria-label="Hero slides">{heroSlides.map((slide,i)=><button key={slide.image} type="button" aria-label={String(i+1)} aria-current={i===heroIndex} className={i===heroIndex?"active":""} onClick={()=>setHeroIndex(i)} />)}</div>
  </section>

  <div className="quick-actions"><button onClick={()=>setActive("ticket")}>🎫 {L.ticket}</button><button onClick={()=>setActive("fare")}>💳 {L.fare}</button><button onClick={()=>setActive("report")}>📝 {L.report}</button><button onClick={()=>setActive("emergency")}>🚨 {L.emergency}</button></div>

  <div className="section-heading"><div><span className="eyebrow dark">ETHIO TRANSPORT</span><h2>{L.services}</h2></div><span className="service-count">{serviceData.length}</span></div>
  <div className="grid">{serviceData.map((s,i)=>{const visuals=cardVisualSets[i];const image=visuals[cardVisualIndex%visuals.length];return <button className={"card card-"+s.visual} key={s.id} onClick={()=>{setActive(s.id);setStatus("");setRef("")}}>
   <div className="card-image"><img src={image} alt="" loading="lazy"/><div className="image-shade"></div><div className="card-title-overlay"><span>{s.icon}</span><h3>{serviceText(lang,s.id).title}</h3></div><span className="card-arrow">↗</span></div>
   <div className="card-body"><div className="card-kicker">{s.en.toUpperCase()}</div><p>{serviceText(lang,s.id).desc}</p><span className="open">{L.open} →</span></div>
  </button>})}</div>

  {active&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setActive(null)}}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="service-title">
   <div className="modal-hero"><img src={selected?.image} alt="" /><div><span className="eyebrow dark">{L.active}</span><h2 id="service-title">{serviceText(lang,active).title}</h2></div><button className="close" onClick={()=>setActive(null)}>{L.close} ×</button></div>
   <div className="modal-content">

   {active==="origin"&&<form className="feature-form" onSubmit={findRoute}><div className="form-grid"><label>{L.from}<input value={origin} onChange={e=>setOrigin(e.target.value)} placeholder={L.from}/></label><label>{L.to}<input value={destination} onChange={e=>setDestination(e.target.value)} placeholder={L.to}/></label><label>{L.date}<input type="date" value={tripDate} onChange={e=>setTripDate(e.target.value)}/></label></div><div className="action-row"><button className="primary" disabled={routeLoading}>🧭 {routeLoading?(lang==="am"?"እየፈለገ ነው…":lang==="en"?"Finding…":"Barbaadaa jira…"):L.find}</button>{routeData&&<a className="outline" target="_blank" rel="noreferrer" href={routeData.mapsUrl}>{L.map} ↗</a>}</div>{routeData&&<div className="route-result"><div><span>{L.distance}</span><strong>{routeData.distanceKm} km</strong></div><div><span>{lang==="am"?"የጉዞ ጊዜ":lang==="en"?"Travel time":"Yeroo imalaa"}</span><strong>{routeData.durationMinutes!=null?Math.round(routeData.durationMinutes)+" min":"—"}</strong></div><small>{routeData.estimated?(lang==="am"?"ግምታዊ ርቀት":"Estimated distance"):routeData.provider}</small></div>}{status&&<div className="info-strip"><strong>{status}</strong></div>}<div className="info-strip"><strong>{L.routeNote}</strong></div></form>}

   {active==="fare"&&<div className="feature-form"><div className="fare-layout"><div className="fare-visual"><span>💳</span><strong>{L.fare}</strong><small>{L.calculate}</small></div><div className="form-grid"><label>{L.distance}<input inputMode="decimal" value={fareKm} onChange={e=>setFareKm(e.target.value)} placeholder={routeData?.distanceKm?"":"10"}/></label><label>{lang==="am"?"አገልግሎት":lang==="en"?"Service":"Tajaajila"}<select value={fareType} onChange={e=>{setFareType(e.target.value);setFareRate("");setFareSource("");setFareResult(null)}}><option value="bus">{lang==="am"?"አውቶቡስ":lang==="en"?"Bus":"Baasi"}</option><option value="taxi">{lang==="am"?"ታክሲ":lang==="en"?"Taxi":"Taaksii"}</option><option value="rail">{lang==="am"?"ባቡር":lang==="en"?"Rail":"Baabura"}</option></select></label></div></div><div className="action-row"><button className="outline" type="button" onClick={loadVerifiedFare} disabled={fareLoading}>✓ {fareLoading?(lang==="am"?"እየፈለገ…":lang==="en"?"Checking…":"Ilaalaa jira…"):(lang==="am"?"የተረጋገጠ ታሪፍ ፈልግ":lang==="en"?"Get verified fare":"Kaffaltii mirkanaa'e barbaadi")}</button><button className="primary" type="button" onClick={()=>{const k=Number(fareKm),r=Number(fareRate);setFareResult(Number.isFinite(k*r)&&k>=0&&r>=0&&fareRate!==""?k*r:null)}}>{L.calculate}</button></div>{fareSource&&<div className="info-strip"><strong>{fareSource}</strong></div>}{fareResult!==null&&<div className="big-result"><span>{L.fare}</span><strong>{fareResult.toFixed(2)} ETB</strong><small>{fareKm} km × {fareRate} ETB/km</small></div>}{status&&<div className="info-strip"><strong>{status}</strong></div>}<div className="info-strip"><strong>{L.calcNote}</strong></div></div>}

   {active==="ticket"&&<div className="ticket-hub"><div className="ticket-banner"><div><span className="eyebrow">{L.live}</span><h3>{L.ticketTitle}</h3><p>{L.ticketIntro}</p></div><span className="ticket-badge">8 PLATFORMS</span></div><h3 className="subheading">{L.platforms}</h3><div className="platform-grid">{ticketItems.map(p=><a className="platform-card" key={p.name} href={p.url} target="_blank" rel="noreferrer"><img src={p.image} alt={p.name} loading="lazy"/><div><strong>{p.name}</strong><span>{p.meta}</span><b>{L.book} ↗</b></div></a>)}</div><h3 className="subheading">{L.buses}</h3><div className="operator-grid">{operatorItems.map((p:any,i:number)=><div className="operator" key={p.name}><img src={p.image} alt={p.name} loading="lazy"/><div><span>{String(i+1).padStart(2,"0")}</span><strong>{p.name}</strong><small>{p.source}</small><a href={p.url} target="_blank" rel="noreferrer">{L.book} ↗</a></div></div>)}</div><div className="info-strip"><strong>{L.ticketNote}</strong></div></div>}

   {active==="report"&&<form className="feature-form" onSubmit={submitReport}><div className="form-grid"><label>{L.name}<input value={report.name} onChange={e=>setReport({...report,name:e.target.value})}/></label><label>{L.phone}<input value={report.phone} onChange={e=>setReport({...report,phone:e.target.value})}/></label><label>{L.category}<select value={report.category} onChange={e=>setReport({...report,category:e.target.value})}><option>{L.fare}</option><option>Route / vehicle</option><option>Safety</option><option>{L.ticket}</option><option>{L.access}</option><option>{L.other}</option></select></label><label>{L.location}<div className="inline"><input value={report.location} onChange={e=>setReport({...report,location:e.target.value})}/><button type="button" className="outline icon-btn" onClick={locate}>📍</button></div></label></div><label>{L.description}<textarea required minLength={5} value={report.description} onChange={e=>setReport({...report,description:e.target.value})}/></label><button className="primary" disabled={!reportReady}>📝 {L.send}</button>{status&&<div className="big-result"><span>{status}</span>{ref&&<strong>{ref}</strong>}</div>}</form>}

   {active==="map"&&<div className="feature-form"><div className="map-preview"><div>📍</div><strong>{L.location}</strong><span>{coords?coords.lat.toFixed(6)+", "+coords.lon.toFixed(6):"GPS location not captured"}</span></div><div className="action-row"><button className="primary" onClick={locate}>📍 {L.useGps}</button>{coords&&<a className="outline" target="_blank" rel="noreferrer" href={"https://www.google.com/maps/search/?api=1&query="+coords.lat+","+coords.lon}>{L.map} ↗</a>}</div></div>}

   {active==="emergency"&&<div className="emergency-grid">{(emergencyContacts.length?emergencyContacts:[{name:"Addis Ababa Police",name_am:"የአዲስ አበባ ፖሊስ",name_om:"Poolisii Finfinnee",name_en:"Addis Ababa Police",phone:"991"},{name:"Sidama Police",name_am:"የሲዳማ ፖሊስ",name_om:"Poolisii Sidaamaa",name_en:"Sidama Police",phone:"8295"},{name:"Federal Police",name_am:"የፌዴራል ፖሊስ",name_om:"Poolisii Federaalaa",name_en:"Federal Police",phone:"990"},{name:"Red Cross emergency",name_am:"ቀይ መስቀል",name_om:"Fannoo Diimaa",name_en:"Red Cross emergency",phone:"907"},{name:"Fire emergency",name_am:"የእሳት አደጋ",name_om:"Balaa ibiddaa",name_en:"Fire emergency",phone:"912"}]).map((x,i)=><a className={"emergency-card "+(i===0?"red":"")} key={x.name+x.phone} href={"tel:"+x.phone}><span>{x.phone==="991"?"🚔":x.phone==="990"?"📞":x.phone==="907"?"🚑":x.phone==="912"?"🔥":"🚨"}</span><strong>{lang==="am"?x.name_am:lang==="en"?x.name_en:x.name_om}</strong><b>{x.phone}</b><small>{x.area||L.emergency}</small></a>)}</div>}

   {active==="trusted"&&<div className="feature-form"><div className="form-grid"><label>{L.from}<input value={trip.origin} onChange={e=>setTrip({...trip,origin:e.target.value})}/></label><label>{L.to}<input value={trip.destination} onChange={e=>setTrip({...trip,destination:e.target.value})}/></label><label>{L.time}<input type="datetime-local" value={trip.time} onChange={e=>setTrip({...trip,time:e.target.value})}/></label></div><label>{L.notes}<textarea value={trip.notes} onChange={e=>setTrip({...trip,notes:e.target.value})}/></label><button className="primary" onClick={addTrip}>🛡️ {L.save}</button>{savedTrips.length>0&&<div className="saved-list">{savedTrips.map(x=><div className="saved-item" key={x.id}><strong>{x.origin} → {x.destination}</strong><span>{x.time||x.createdAt}</span></div>)}</div>}</div>}

   {active==="access"&&<div className="feature-form"><div className="access-options">{[[L.wheel,"Wheelchair access"],[L.vision,"Visual assistance"],[L.hearing,"Hearing assistance"],[L.elderly,"Elderly assistance"],[L.other,"Other"]].map(([label,value])=><button type="button" key={value} className={accessNeed===value?"selected":""} onClick={()=>setAccessNeed(value)}>{label}</button>)}</div><button className="primary" onClick={saveAccess}>♿ {L.save}</button>{status&&<div className="info-strip"><strong>{status}</strong></div>}</div>}

   {active==="parcel"&&<div className="feature-form"><div className="form-grid"><label>{L.from}<input value={parcel.from} onChange={e=>setParcel({...parcel,from:e.target.value})}/></label><label>{L.to}<input value={parcel.to} onChange={e=>setParcel({...parcel,to:e.target.value})}/></label></div><label>{L.parcelDetails}<textarea value={parcel.description} onChange={e=>setParcel({...parcel,description:e.target.value})}/></label><div className="action-row"><button className="primary" onClick={saveParcel}>📦 {L.save}</button><a className="outline" href="https://i-ticket.et/" target="_blank" rel="noreferrer">{L.check} ↗</a></div>{status&&<div className="info-strip"><strong>{status}</strong></div>}</div>}

   {active==="offline"&&<div className="offline-grid"><div className="offline-card"><span>🛡️</span><strong>{savedTrips.length} {L.savedTrips}</strong><small>{L.saved}</small></div><div className="offline-card"><span>📝</span><strong>{load<any[]>("ethio_transport_reports",[]).length} {L.savedReports}</strong><small>{load<QueuedAction[]>("ethio_transport_sync_queue",[]).length} {L.pending}</small></div><div className="offline-card"><span>📡</span><strong>{L.low}</strong><small>{L.official}</small></div></div>}
   </div></section></div>}

  <footer><strong>ETHIO TRANSPORT</strong><span>{L.sub} • {L.official}</span><a href="/privacy" className="privacy-link">Privacy Policy</a></footer>
 </main>
}